CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), sku text NOT NULL, name text NOT NULL, category text NOT NULL DEFAULT '', cost_price numeric(18,2) NOT NULL DEFAULT 0, selling_price numeric(18,2) NOT NULL DEFAULT 0, current_stock numeric(18,3) NOT NULL DEFAULT 0, minimum_stock numeric(18,3) NOT NULL DEFAULT 0, reorder_level numeric(18,3) NOT NULL DEFAULT 0, preferred_supplier_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,sku), UNIQUE(organization_id,id)); CREATE INDEX products_org_idx ON products(organization_id);
